import React, { useState } from 'react';
import './CSS/AdminDashboard.css';
import { Link } from 'react-router-dom';

const AdminDashboard = () => {
  const [activeTab, setActiveTab] = useState('overview');
  const [selectedUser, setSelectedUser] = useState(null);

  const [users, setUsers] = useState([
    { 
      id: '#101', 
      name: 'Anisha', 
      email: 'anisha@seller.com', 
      role: 'Seller', 
      status: 'Active', 
      joined: '2026-02-10',
      activities: [
        { date: '2026-03-08 14:20', action: 'Listed new product: "Wireless Headphones"' },
        { date: '2026-03-07 10:15', action: 'Fulfilled Order #ORD-882' },
        { date: '2026-02-10 09:00', action: 'Seller account registered and verified' }
      ]
    },
    { 
      id: '#102', 
      name: 'Mona', 
      email: 'mona@gmail.com', 
      role: 'User', 
      status: 'Active', 
      joined: '2026-02-14',
      activities: [
        { date: '2026-03-08 16:05', action: 'Placed an order #ORD-991' },
        { date: '2026-03-08 12:30', action: 'Logged in successfully' },
        { date: '2026-02-14 11:45', action: 'Created account' }
      ]
    },
    { 
      id: '#103', 
      name: 'Jhanvi', 
      email: 'jhanvi@gmail.com', 
      role: 'User', 
      status: 'Active', 
      joined: '2026-03-01',
      activities: [
        { date: '2026-03-05 18:22', action: 'Added items to cart' },
        { date: '2026-03-01 08:30', action: 'Created account' }
      ]
    },
    { 
      id: '#104', 
      name: 'Bharath', 
      email: 'bharath@seller.com', 
      role: 'Seller', 
      status: 'Blocked', 
      joined: '2026-03-05',
      activities: [
        { date: '2026-03-07 15:10', action: 'Account flagged for high cancellation rate' },
        { date: '2026-03-05 13:00', action: 'Seller account registered' }
      ]
    },
  ]);

  const toggleStatus = (id) => {
    setUsers(users.map(u => u.id === id ? { ...u, status: u.status === 'Active' ? 'Blocked' : 'Active' } : u));
  };

  const toggleUserActivity = (user) => {
    if (selectedUser && selectedUser.id === user.id) {
      setSelectedUser(null);
    } else {
      setSelectedUser(user);
    }
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'overview':
        return (
          <div className="tab-panel">
            <div className="panel-header">
              <h2>System Analytics & Overview</h2>
              <span className="timestamp">Live System Status</span>
            </div>

            {/* KPI Cards */}
            <div className="stats-cards">
              <div className="card border-blue">
                <div className="card-info">
                  <h3>Total Registered Users</h3>
                  <p className="card-value">{users.filter(u => u.role === 'User').length}</p>
                </div>
                <span className="card-icon"></span>
              </div>
              <div className="card border-purple">
                <div className="card-info">
                  <h3>Verified Sellers</h3>
                  <p className="card-value">{users.filter(u => u.role === 'Seller').length}</p>
                </div>
                <span className="card-icon"></span>
              </div>
              <div className="card border-green">
                <div className="card-info">
                  <h3>Active Accounts</h3>
                  <p className="card-value">{users.filter(u => u.status === 'Active').length}</p>
                </div>
                <span className="card-icon"></span>
              </div>
              <div className="card border-red">
                <div className="card-info">
                  <h3>Blocked / Suspended</h3>
                  <p className="card-value">{users.filter(u => u.status === 'Blocked').length}</p>
                </div>
                <span className="card-icon"></span>
              </div>
            </div>

            {/* Platform Metrics Breakdown */}
            <div className="overview-sections">
              <div className="overview-box">
                <h3>Quick Platform Health</h3>
                <div className="health-item">
                  <span>Account Operational Rate</span>
                  <div className="progress-bar">
                    <div 
                      className="progress-fill" 
                      style={{ width: `${(users.filter(u => u.status === 'Active').length / users.length) * 100}%` }}
                    ></div>
                  </div>
                </div>
                <div className="health-item">
                  <span>Seller to Buyer Ratio</span>
                  <p className="metric-text">
                    {users.filter(u => u.role === 'Seller').length} Sellers : {users.filter(u => u.role === 'User').length} Buyers
                  </p>
                </div>
              </div>

              <div className="overview-box">
                <h3>Recent Security & Admin Events</h3>
                <ul className="mini-events">
                  <li> User <strong>Mona (#102)</strong> logged in.</li>
                  <li> Seller account <strong>Bharath (#104)</strong> flag updated to <strong>Blocked</strong>.</li>
                  <li> Database security policies synced on port 4000.</li>
                </ul>
              </div>
            </div>
          </div>
        );

      case 'users':
        return (
          <div className="tab-panel">
            <h2>User Management & Activity</h2>
            <table className="admin-table">
              <thead>
                <tr>
                  <th>ID</th><th>Name</th><th>Email</th><th>Status</th><th>Action</th><th>Activity Log</th>
                </tr>
              </thead>
              <tbody>
                {users.filter(u => u.role === 'User').map(user => (
                  <React.Fragment key={user.id}>
                    <tr>
                      <td>{user.id}</td>
                      <td>{user.name}</td>
                      <td>{user.email}</td>
                      <td><span className={`badge ${user.status.toLowerCase()}`}>{user.status}</span></td>
                      <td>
                        <button 
                          className={`action-btn ${user.status === 'Active' ? 'block' : 'grant'}`}
                          onClick={() => toggleStatus(user.id)}
                        >
                          {user.status === 'Active' ? 'Block Access' : 'Grant Access'}
                        </button>
                      </td>
                      <td>
                        <button className="view-btn" onClick={() => toggleUserActivity(user)}>
                          {selectedUser?.id === user.id ? 'Hide Activity' : 'View Activity'}
                        </button>
                      </td>
                    </tr>
                    {selectedUser?.id === user.id && (
                      <tr className="activity-row">
                        <td colSpan="6">
                          <div className="activity-container">
                            <h4>Recent Actions by {user.name} ({user.id})</h4>
                            <ul>
                              {user.activities.map((act, idx) => (
                                <li key={idx}>
                                  <span className="activity-date">[{act.date}]</span> {act.action}
                                </li>
                              ))}
                            </ul>
                          </div>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                ))}
              </tbody>
            </table>
          </div>
        );

      case 'sellers':
        return (
          <div className="tab-panel">
            <h2>Seller Management & Verification</h2>
            <table className="admin-table">
              <thead>
                <tr>
                  <th>ID</th><th>Store Name</th><th>Email</th><th>Status</th><th>Action</th><th>Activity Log</th>
                </tr>
              </thead>
              <tbody>
                {users.filter(u => u.role === 'Seller').map(seller => (
                  <React.Fragment key={seller.id}>
                    <tr>
                      <td>{seller.id}</td>
                      <td>{seller.name}</td>
                      <td>{seller.email}</td>
                      <td><span className={`badge ${seller.status.toLowerCase()}`}>{seller.status}</span></td>
                      <td>
                        <button 
                          className={`action-btn ${seller.status === 'Active' ? 'block' : 'grant'}`}
                          onClick={() => toggleStatus(seller.id)}
                        >
                          {seller.status === 'Active' ? 'Block Store' : 'Approve Store'}
                        </button>
                      </td>
                      <td>
                        <button className="view-btn" onClick={() => toggleUserActivity(seller)}>
                          {selectedUser?.id === seller.id ? 'Hide Activity' : 'View Activity'}
                        </button>
                      </td>
                    </tr>
                    {selectedUser?.id === seller.id && (
                      <tr className="activity-row">
                        <td colSpan="6">
                          <div className="activity-container">
                            <h4>Store Activities for {seller.name} ({seller.id})</h4>
                            <ul>
                              {seller.activities.map((act, idx) => (
                                <li key={idx}>
                                  <span className="activity-date">[{act.date}]</span> {act.action}
                                </li>
                              ))}
                            </ul>
                          </div>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                ))}
              </tbody>
            </table>
          </div>
        );

      case 'logs':
        return (
          <div className="tab-panel">
            <h2>Activity Audit Logs</h2>
            <ul className="log-list">
              {users.flatMap(u => u.activities.map(act => ({ ...act, name: u.name, role: u.role, id: u.id }))).map((log, idx) => (
                <li key={idx}>
                  <span className="log-tag">[{log.role}]</span> <strong>{log.name} ({log.id})</strong>: {log.action} <em className="log-time">({log.date})</em>
                </li>
              ))}
            </ul>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="admin-standalone-container">
      {/* Top Admin Bar */}
      <header className="admin-topbar">
        <div className="admin-brand">
          <h2>HEX<span>CART</span> <small>Control Center</small></h2>
        </div>
        <div className="admin-actions">
          <Link to="/" className="btn-storefront"> Return to Store</Link>
          <button onClick={() => { localStorage.clear(); window.location.replace('/'); }} className="btn-logout">
            Logout
          </button>
        </div>
      </header>

      <div className="admin-layout">
        {/* Sidebar */}
        <aside className="admin-sidebar">
          <nav className="sidebar-menu">
            <button className={activeTab === 'overview' ? 'active' : ''} onClick={() => { setActiveTab('overview'); setSelectedUser(null); }}>
               Overview
            </button>
            <button className={activeTab === 'users' ? 'active' : ''} onClick={() => { setActiveTab('users'); setSelectedUser(null); }}>
               User Activity
            </button>
            <button className={activeTab === 'sellers' ? 'active' : ''} onClick={() => { setActiveTab('sellers'); setSelectedUser(null); }}>
               Seller Activity
            </button>
            <button className={activeTab === 'logs' ? 'active' : ''} onClick={() => { setActiveTab('logs'); setSelectedUser(null); }}>
               Audit Logs
            </button>
          </nav>
        </aside>

        {/* Content */}
        <main className="admin-content">
          {renderContent()}
        </main>
      </div>
    </div>
  );
};

export default AdminDashboard;
